<?php
namespace App\Services; use App\Contracts\PaymentProvider; use Illuminate\Support\Str;
class TilopayProvider implements PaymentProvider { public function create(array $p):array{return ['provider'=>'tilopay','reference'=>'sandbox_'.Str::uuid(),'status'=>'pending','checkout_url'=>config('payments.tilopay.base_url').'/sandbox/checkout'];} public function query(string $reference):array{return ['reference'=>$reference,'status'=>'pending'];} public function refund(string $reference,int $amount,string $currency):array{return ['reference'=>$reference,'status'=>'pending','amount'=>$amount,'currency'=>$currency];} public function verifyWebhook(string $payload,?string $signature):bool{$secret=config('payments.tilopay.secret');return $secret!==null&&$secret!==''&&$signature!==null&&hash_equals(hash_hmac('sha256',$payload,$secret),$signature);} }
